// SOURCE: Found in connected workspace root (Claude Cowork - Zingtree/quest_consent_dictionary.js); Quest Diagnostics account work
// ACCOUNT: Quest Diagnostics
// PURPOSE: Zingtree Script Node. Static dictionary of per-company consent texts; looks up by ZT.getVariableValue('company','') and exposes via ZT.setFormData('consent_instruction', ...).

var dictionary = {
  "AutoNation Consent": "By registering for and participating in the AutoNation MSRP biometric screening program, I understand and agree that my individual test results will be shared with certain contracted third parties including, but not limited to, insurance carriers and AutoNation Benefit Plan (\"Plan\") consultants.\n\nBy clicking \"I Agree\" below, I am providing consent to the secure and confidential transfer of my test results to contracted third parties for the purpose of enhancing patient care services, assisting with Plan communications and/or Plan administration and management and processing my screening results and determining which healthy incentive credits apply to me.\n\nIn order to be eligible for healthy incentive credits, I must fully participate in all required screening components and testing procedures.\n\nAutoNation will NOT receive individual biometric screening results.\n\nIf I do not pass 3 of 5 MSRP biometric lab risk factors I acknowledge and agree The Benefit Connection will notify me via my preferred email address (if I established one) or my AutoNation email address registered on The Benefit Connection website, of the alternate methods for earning the healthy incentive credits.\n\nIf I am the spouse of an AutoNation employee I am acknowledging and consenting that the email for me will be sent to my preferred email (if applicable) or my spouse's AutoNation email address registered on The Benefit Connection website.\n\nThe actual results of my MSRP biometric screening will not be reported to The Benefit Connection, simply an indicator noting if I am eligible for the healthy credits based on my screening.",
  "Honeywell International Inc": "Honeywell's wellness program (the Program) is voluntary and available to all employees.\n\nBy completing a biometric screening, you authorize the results to be sent from Quest Diagnostics to applicable service providers associated with the Program (Service Providers) including Cigna or Castlight Health, for health navigation services, and Merative, a healthcare analytics solution provider.\n\nWe are required by law to maintain the privacy and security of your personally identifiable health information.\n\nAlthough the Program and Honeywell may use aggregate information collected to design a program based on identified health risks in the workplace, neither the Program nor the Service Providers will disclose any of your personal information either publicly or to Honeywell, except as necessary to respond to a request from you for a reasonable accommodation needed to participate in the Program, or as expressly permitted by law.\n\nMedical information that personally identifies you that is provided in connection with the Program will not be provided to your supervisors or managers and may never be used to make decisions regarding your employment.",
  "BCBS of Alabama Custom Consent": "I understand that this screening service is offered for my benefit and information.\n\nScreening tests are not meant to replace the care of my personal physician.\n\nI acknowledge that I may receive results that are considered \"out of range\" as well as an explanation for these results.\n\nHowever, I also understand that screening tests can give false positive or negative results for a variety of reasons.\n\nI acknowledge that my physician is best able to interpret the results of these tests based on his/her understanding of my medical history.\n\nI also acknowledge that I have received a copy of my group health plan's Notice of Privacy Practices and understand such Notice provides an explanation of the ways that my individual health information may be stored, used or disclosed by my group health plan and those acting on behalf of my group health plan (for example group health plan and its business associates WebMD, and Quest Diagnostics), and of my rights with respect to my health information.\n\nThis means, among other things, that my group health plan may use and disclose my wellness screening results for the group health plan's healthcare operations.\n\nI have been provided the opportunity to discuss concerns I may have regarding the privacy of my health information.\n\nI understand that Quest Diagnostics may share my wellness screening results with group health plan (and its business associate WebMD) if I am, or become, a registered user of the WebMD internet tools provided by group health plan for use by my group health plan's members.\n\nI release and discharge my group health plan, Quest Diagnostics, WebMD and their shareholders, parent, subsidiaries, officers, directors, employees, franchisees, licensees, vendors used to conduct lab analyses, subcontractors and, respective affiliates, and the program sponsors, including, without limitation, WebMD and their agents, including the owners/operators of this facility and its parent, subsidiaries, officers, directors and employees (collectively, the \"Released Parties\"), from any and all claims or causes of action, on account of injury to me which may result from my participation in this screening (including a failure of the screening to detect any particular health problem), except for such claims or causes of action on account of injury to me resulting from the sole negligent acts or omissions, or willful misconduct, of the Released Parties.\n\nThis release shall be binding upon my heirs, assigns, executors, administrators and representatives.\n\nQuest Diagnostics and WebMD are independent companies that provide worksite wellness services to group health plan customers.",
  "ParTNers For Health Consent": "I consent to participate in\n\nActive Health Management's Health Risk Screening and Support Program (the \"Program\"), which may include providing biometric measurements such as weight and blood pressure, disclosing laboratory results from a recent blood test with my personal physician, and/or completing an on-line or written Health Risk Assessment.\n\nI understand that my participation in the Program is voluntary and that I am not required to participate as a condition of employment or of enrollment in my health plan.\n\nI understand and consent to my personal physician providing to Quest on behalf of ActiveHealth Management results from a blood draw and laboratory analysis performed by my physician within the past twelve (12) months for the tests listed below.\n\nI agree to execute any authorization form required by my physician prior to disclosing my results to ActiveHealth Management.\n\nSuch results will include lipids (cholesterol and components) and blood glucose measurements in addition to blood pressure, height, weight and waist.\n\nI consent to Quest providing me with a report (either on-line or in writing) of my Program results and, if applicable, periodically providing me with follow-up educational materials and information relevant to my Program results.\n\nThe laboratory results reflected in my report are for informational purposes only and are NOT a medical diagnosis.\n\nI understand that the Program is sponsored by my employer or benefits provider.\n\nIf an incentive is implemented as part of the Program, I consent to Quest informing my Sponsor only whether or not I qualify for such incentive based upon my participation in the Program.\n\nI understand that if I do not elect to provide such consent, I may not qualify for such incentive.\n\nI understand that my individual health data will be used by ActiveHealth Management and will be treated as confidential in accordance with the Health Insurance Portability and Accountability Act of 1996 (HIPAA).\n\nIndividual health information will be shared between my physician or care provider and Quest, however individual information will not be shared with my employer.\n\nI understand that ActiveHealth Management will not disclose my individual health information to my employer.\n\nAggregated data (i.e., data with no individual identifiers) on all participants, however, may be shared with employer.\n\nI understand that my employer or benefits provider may from time to time offer enrollees other health and wellness services and programs (collectively, \"Other Health/Wellness Programs\"), such as employee assistance and/or disease management programs.\n\nI consent to the disclosure by ActiveHealth Management of my wellness screening results and/or other personal health information that identifies me to ActiveHealth Management' other Health/Wellness Programs so that they may contact me for the purpose of addressing my particular health/wellness needs.\n\nI understand that ActiveHealth Management and/or my employer or benefits provider will require such Other Health/Wellness Program providers to agree to maintain the confidentiality of any wellness screening results and/or other personal health information provided to them by ActiveHealth Management in accordance with the applicable regulations under HIPAA.\n\nI understand that if I do not want ActiveHealth Management to disclose my wellness screening results and/or other personal health information to Other Health/Wellness Program providers sponsored by my employer or benefits provider, I must notify ActiveHealth Management in writing at:\nActiveHealth Management, PO Box 221138, Chantilly VA 20153-1138 Attn:\nScreening Operations.\n\nI understand that this consent will remain in effect for as long as I participate in the Program, and that I am entitled to a copy of this consent.\n\nI may revoke this consent at any time by notifying ActiveHealth Management in writing, to the extent ActiveHealth Management has not already relied on this consent.",
  "Solutions Program Authorization for Release of Health Screening Results  Rock and Roll Hall of FAme": "The Genetic Information Nondiscrimination Act of 2008 (GINA) prohibits employers and other entities covered by GINA Title II from requesting or requiring genetic information of an individual or family member of the individual, except as specifically allowed by this law.\n\nTo comply with this law, we are asking that you not provide any genetic information when responding to this request for medical information.\n'Genetic information' as defined by GINA, includes an individual's family medical history, the results of an individual's or family member's genetic tests, the fact that an individual or an individual's family member sought or received genetic services, and genetic information of a fetus carried by an individual or an individual's family member or an embryo lawfully held by an individual or family member receiving assistive reproductive services.\n\nI authorize Medical Mutual of Ohio and its subsidiaries and affiliated companies (collectively, \"Medical Mutual\") to release to Rock & Roll Hall of Fame the number of health factors I met gathered from my health screening for the purposes of coordinating with the Rock & Roll Hall of Fame or the receipt of wellness benefits.\n\nNo specific results, including the specific factors met or not met nor the specific measures or test results will be shared with my employer.\n\nI understand information used or disclosed pursuant to this Authorization may be subject to re-disclosure by the Rock & Roll Hall of Fame and may no longer be protected by Federal or State privacy laws.\n\n**`I understand this authorization is voluntary, my participation in the wellness program is voluntary, and I will not be penalized if I choose not to participate in the Outcomes-Based Wellness Program.`**\nI may revoke this authorization at any time by delivering such revocation in writing to Medical Mutual at:\nWellness Team;\nMZ:\n01-5B-7500;\nMedical Mutual 2060 East 9th Street;\nCleveland, Ohio 44115.\n\nI further understand Medical Mutual may not condition treatment, payment, enrollment or eligibility for benefits on my signing this Authorization.\n\nI hereby release Medical Mutual from all legal responsibilities or liabilities that may arise from any use or disclosure of information made pursuant to this Authorization, and further understand and agree that any use of my individual health information by the Rock & Roll Hall of Fame is independent from the health plan programs and services provided by Medical Mutual.\n\nThis Authorization shall remain in effect as long as I participate in my employer's wellness program, unless revoked earlier by me in writing.\n\nI certify that I have read, understand and agree to this Authorization.",
  "ShareCare 1272020": "Wellness Notice and Consent\n\nI agree to participate in Sharecare's Health Risk Screening and Support Program (the \"Program\").\n\nI understand the Program is offered by my health plan or my employer as the sponsor of my health plan (\"Sponsor\").\n\nI understand that completion of this biometric screening or vaccination is voluntary.\n\nIf I choose not to participate or do not give my permission by signing this authorization form and completing this screening, I understand that I may not be able to receive Program incentives (if offered).\n\nThe biometric screening data includes data which may be considered genetic information.\n\nI further understand that if choose to participate in the biometric screening or vaccination, any health and genetic information obtained in the screening will not be sold, exchanged, transferred, or otherwise disclosed except to the extent permitted by law to carry out specific activities related to the wellness program.\n\nThe Program may include the administration of a vaccination or collecting blood, by fingerstick or through a vein (venipuncture), for testing, identifying your unique behaviors (biometric measurements), completing a health risk or well-being assessment or other wellness activities.\n\nThe blood test include but are not limited to:\nTotal Cholesterol, High Density Lipoprotein (HDL), Low Density Lipoprotein (LDL), Triglycerides, Glucose, Cotinine, Gamma-Glutamyl Transferase (GGT), Albumin, Bilirubin, Blood Urea Nitrogen (BUN), Calcium, Globulin, Lactic Dehydrogenase, Phosphate/Alkaline, Protein, Serum Creatinine, Transferase Alanine, Transferase Asparte, Uric Acid, Very low density lipoprotein.\n\nThis collection may also include recording of biometric measurements of Height, Weight, Waist Circumference, Blood Pressure and calculated Body Mass Index (BMI).\n\nIf a blood sample is included in the Program (by fingerstick or venipuncture), I give my permission to have my blood drawn and agree that I have been made aware of the possible related risks.\n\nThese risks may include infection, soreness and bruising.\n\nI understand that more risks may occur and the information I have been given is enough for me to give my permission for the collection of my blood sample.\n\nI also give my permission for my blood sample to be studied, in a laboratory (working with Sharecare) or at the onsite screening, and if a laboratory is used, it may give my results to Sharecare.\n\nI release Sharecare, the laboratory and other companies or people working with the Program from any and all liability coming from Program screenings, the collection of my blood sample, the laboratory study of my blood sample, if needed, and the report of the study of my blood sample.\n\nI understand that all information and comments I receive through the Program, including any test results, are early pieces of information gathered through the brief review that has taken place, and are NOT a medical diagnosis or opinion.\n\nParticipation in the Program does not take the place of professional medical advice.\n\nI must call or visit my doctor to talk about any questions I have about my test, screening, or lab results or to get medical opinions.\n\nI understand and give my permission for Sharecare to use and share my personal health information as allowed by law, including the Health Insurance Portability and Accountability Act of 1996 (HIPAA).\n\nMy personal health information may have my name, participation status, screening results, vaccination date and other information.\n\nI also give my permission for Sharecare to share my information in order to operate the Program, and to other programs offered by my Sponsor to provide wellness services to me.\n\nSharecare may depend on my permission for as long as I participate in the Program.\n\nI may revoke this permission at any time by writing to Sharecare.\n\nThe removal of my permission does not apply to any use or sharing of my information by Sharecare before I write to them.\n\nAny notice to Sharecare should be mailed to Sharecare, 255 East Paces Ferry Road\n\nNortheast,\n\nSuite 700, Atlanta, GA 30305, Attention:\nPrivacy Office",
  "SHBP 2020": "Wellness Notice and Consent\n\nI agree to participate in Sharecare's Health Risk Screening and Support Program (the \"Program\").\n\nI understand the Program is administered by Sharecare on behalf of the State Health Benefit Plan (\"Sponsor\").\n\nI understand that completion of this biometric screening is voluntary.\n\nIf I choose not to participate or do not give my permission by signing this authorization form and completing this screening, I understand that I may not be able to receive the Program incentives (if offered).\n\nThe biometric screening data includes data which may be considered genetic information.\n\nI further understand that if I choose to participate in the screening, any health and genetic information obtained in the screening will not be sold, exchanged, transferred, or otherwise disclosed except to the extent permitted by law to carry out specific activities related to the wellness program.\n\nI understand that the Program may include collecting blood, by fingerstick or through a vein (venipuncture), for testing, identifying my unique behaviors (biometric measurements), completing a health risk or well-being assessment or other wellness activities.\n\nThe blood tests include but are not limited to:\nTotal Cholesterol, High Density Lipoprotein (HDL), Low Density Lipoprotein (LDL), Triglycerides, Glucose, and HbA1c.\n\nThis collection may also include recording of biometric measurements of height, weight, waist circumference, blood pressure and calculated Body Mass Index (BMI).\n\nIf a blood sample is included in the Program (by fingerstick or venipuncture), I give my permission to have my blood drawn and agree that I have been made aware of the possible related risks.\n\nThese risks may include infection, soreness and bruising.\n\nI understand that more risks may occur and the information I have been given is enough for me to give my permission for the collection of my blood sample.\n\nI also give my permission for my blood sample to be studied, in a laboratory (working with Sharecare) or at the onsite screening, and if a laboratory is used, it may give my results to Sharecare.\n\nI release Sharecare, the laboratory and other companies or people working with the Program from any and all liability coming from the Program screenings, the collection of my blood sample, the laboratory study of my blood sample, if needed, and the report of the study of my blood sample.\n\nI understand that all information and comments I receive through the Program, including any test results, are based on the brief review that has taken place, and are NOT a medical diagnosis or opinion.\n\nParticipation in the Program does not take the place of professional medical advice.\n\nI must call or visit my doctor to talk about any questions I have about my test, screening, or lab results or to get medical opinions.\n\nI understand and give my permission for Sharecare to use and share my personal health information as allowed by law, including the Health Insurance Portability and Accountability Act of 1996 (HIPAA).\n\nMy personal health information may have my name, participation status, screening results and other information.\n\nI also give my permission for Sharecare to share my information with my Sponsor or medical claims administrator to operate the Program and with other programs offered by my Sponsor to provide wellness services to me.\n\nI may revoke this permission at any time by writing to Sharecare.\n\nThe revocation of my permission does not apply to any use or sharing of my information by Sharecare before I write to them.\n\nAny notice to Sharecare should be mailed to Sharecare, 701 Cool Springs Blvd., Franklin, TN 37067, Attn:\nPrivacy Officer.",
  "Cigna Consent English 2024": "BIOMETRIC HEALTH\nSCREENING AUTHORIZATION\nFOR DISCLOSURE\nOF PROTECTED\nHEALTH INFORMATION\n\n**I, the undersigned, represent as follows:**\n\n- I understand that my participation in this Biometric Health Screening is voluntary.\n\n- I hereby authorize Quest Diagnostics, which administers this Biometric Health Screening, and Connecticut General Life Insurance Company, Cigna Health and Life Insurance Company Cigna Onsite Health, Inc.\n\n(collectively \"Cigna\"), their affiliates, subsidiaries or agents to disclose the Protected Health Information (PHI) indicated below to the persons or entities specified on this form.\n\n**Description of Information to be Released, Entity or Person Authorized to Receive Information, Purpose for Release of Information:**\n\nMy individually identifiable health information will not be shared with my Employer;\nhowever, my Employer may be advised of my participation in the Biometric Health Screening for purposes of qualification for incentives offered by my Employer.\n\nIf my Employer offers incentives related to \"pass/fail\" test results (including the results of any test for cotinine to indicate tobacco use), my results may be disclosed to my Employer for those incentive purposes.\n\nMy Biometric Health Screening test results may be disclosed to vendors engaged by my Employer or Employer sponsored group health plan, including Cigna and their affiliates and subsidiaries which may include its Supplemental Health Solutions platforms, for purposes of determining my eligibility for an incentive related to this Biometric Health Screening, for health management and/or disease management services including data aggregation for program improvement purposes, for auto payment of a supplemental claim, and/or for purposes of population of my Personal Health Record available online and/or my Health Risk Assessment (HRA).\n\nThe importance of safeguarding individually identifiable health information is recognized, and all organizations involved in this Biometric Health Screening are obligated to take reasonable steps to protect such information from unauthorized access or use.\n\n**Expiration of Authorization:**\nThis authorization expires:\nthe earlier of one year from the date of my signature below, or upon the reporting of the information as described in this Authorization.\n\n**I further understand:**\n\n-\n\nI have the right to revoke this Authorization in writing by sending a written request to:\nQuest Diagnostics Employer Population Health, 27175 Haggerty Road, Novi, MI 48377\n\n-\n\nAny revocation of this Authorization will not apply to any disclosure made prior to Quest's receipt of my revocation.\n\n- The provision of treatment, payment enrollment or eligibility for benefits does not depend on whether I sign this Authorization.\n\n- Information disclosed based on this Authorization may be subject to redisclosure by the recipient and may no longer be protected by federal privacy regulations.",
  "Cigna Consent Spanish 2020": "(c) 2020 Quest Diagnostics CCGASP20180508 AUTORIZACI\u00d3N PARA EVALUACI\u00d3N BIOM\u00c9TRICA DE SALUD, PARA LA DIVULGACI\u00d3N DE INFORMACI\u00d3N DE SALUD PROTEGIDA Yo, el suscrito, declare lo siguiente:\n- Entiendo que mi participaci\u00f3n en este examen de salud biom\u00e9trico es voluntaria.\n- Por la presente autorizo a Quest Diagnostics, quien realiza estos ex\u00e1menes de salud biom\u00e9tricos, y a Connecticut General Life Insurance Company, Cigna Health and Life Insurance Company Cigna Onsite Health Inc.\n\n(a quien colectivamente se denomina \"Cigna\"), sus filiales, subsidiarias o agentes a divulgar la informaci\u00f3n de salud protegida (PHI, por sus siglas en ingl\u00e9s) que abajo se indica a las personas o entidades que se especifican en este formulario.\n\nDescripci\u00f3n de la informaci\u00f3n que se habr\u00e1 de divulgar, la entidad o la persona autorizada para recibir la informaci\u00f3n, prop\u00f3sito de la divulgaci\u00f3n de la informaci\u00f3n:\nMi informaci\u00f3n de salud personal identificable no ser\u00e1 compartida con mi empleador;\nsin embargo, a mi empleador se le podr\u00e1 informar de mi participaci\u00f3n en los ex\u00e1menes de salud biom\u00e9tricos para prop\u00f3sito de calificar para los incentivos ofrecidos por mi empleador.\n\nSi mi empleador ofrece incentivos con relaci\u00f3n a resultados de pasar o no pasar el examen, podr\u00e1 comunicarse mis resultados de pasar o no pasar a mi empleador para prop\u00f3sitos de los incentivos ofrecidos.\n\nLos resultados de los ex\u00e1menes de salud biom\u00e9tricos podr\u00e1n ser revelados a las compa\u00f1\u00edas contratadas por mi empleador o el plan de seguro m\u00e9dico de grupo que ofrece mi empleador, inclusive Cigna y sus filiales y subsidiarias, para el prop\u00f3sito de determinar mi elegibilidad para un incentivo con relaci\u00f3n a este examen de salud biom\u00e9trico;\npara servicios de manejo de la salud o servicios de manejo de enfermedades, inclusive la agregaci\u00f3n de los datos para mejorar el programa;\no para el prop\u00f3sito del ingreso de datos a mi registro personal de salud disponible por la internet o mi evaluaci\u00f3n de riesgos para la salud (HRA).\n\nSe reconoce la importancia de salvaguardar la informaci\u00f3n de salud personal identificable y toda organizaci\u00f3n involucrada con estos ex\u00e1menes de salud biom\u00e9tricos estar\u00e1n obligados a tomar medidas razonables para proteger tal informaci\u00f3n del acceso o uso no autorizado.\n\nVencimiento de Autorizaci\u00f3n:\nEsta autorizaci\u00f3n vence un a\u00f1o de la fecha de mi firma abajo o al reportarse la informaci\u00f3n seg\u00fan se describe en esta autorizaci\u00f3n, lo que ocurra primero.\n\nAsimismo entiendo que:\n\n- Tengo el derecho a revocar esta autorizaci\u00f3n al enviar mi solicitud por escrito dirigida a:\nQuest Diagnostics Employer Population Health, 27175 Haggerty Road, Novi, MI 48377.\n\n- La provisi\u00f3n de tratamiento, reembolso inscripci\u00f3n, o elegibilidad para beneficios no depende de mi firma de esta autorizaci\u00f3n.\n\n- La informaci\u00f3n que se divulgue debido a esta autorizaci\u00f3n podr\u00e1 ser divulgada m\u00e1s adelante por el recipiente, en cuyo caso podr\u00eda ya no disfrutar de la protecci\u00f3n de los reglamentos federales de privacidad.\n\nANTES DE FIRMAR,\naseg\u00farese de haber completado toda la informaci\u00f3n al reverso de esta p\u00e1gina.\n\nHe le\u00eddo y entiendo la informaci\u00f3n anterior.\n\nMi firma autoriza la divulgaci\u00f3n de mi informaci\u00f3n PHI a Cigna.\n\nNombre en letra de imprenta:\nFecha de nacimiento:\nFirma:\nFecha:",
  "Choose Healthy Life HIPAA Authorization": "## Choose Healthy Life HIPAA Authorization ## Quest Diagnostics is the laboratory that will conduct the testing that is part of the Choose\n\nHealthy Life Wellness Program.\n\nQuest Diagnostics and Choose Health Life are committed to\n\ngaining and maintaining your trust, especially concerning the privacy of your information.\n\nQuest Diagnostics complies with a federal law called HIPAA, which stands for the Health\n\nInsurance Portability and Accountability Act of 1996.\n\nHIPAA gives patients certain protections\n\nabout the use of their health information.\n\nQuest Diagnostics is required to get your permission\n\nwhen sharing your health information with other people and organizations in certain situations,\n\nlike for the Choose Healthy Life Wellness Program.\n\nIn order to fully participate in the Choose Healthy Life Wellness Program, Quest Diagnostics\n\nneeds to share some of your personal health information (also known as your protected health\n\ninformation) with people that are not Quest Diagnostics employees.\n\nSharing your protected\n\nhealth information will help Choose Healthy Life perform follow-up activities and provide you\n\nwith additional information for the Program.\n\nMore details about the information that is shared and who will receive it is listed below.\n\nQuest Diagnostics and Choose Healthy Life take your privacy very seriously and want to be sure\n\nthat you are fully informed about how your data will be shared.\n\nOnce you read through this\n\nAuthorization, Quest Diagnostics is asking you for permission to share your protected health information in connection with your participation in the Choose Healthy Life Wellness Program.\n\nWhen you sign this form that is called a HIPAA Authorization, you give Quest Diagnostics\n\npermission to share your protected health information as part of this Program.\n\n**`Authorization to Share PHI`**\n\nI give my permission and authorize Quest Diagnostics Incorporated and its subsidiaries and\n\naffiliates (\"Quest\") to collect, use and disclose my protected health information (also called **PHI**) as described in this Authorization to the groups and individuals that are named as **Recipients**\nlisted below and that are arranging for Quest testing as part of the Choose Healthy Life\n\nWellness Program, which we will call the **Program**\nin this Authorization.\n\nThis Program is paid\n\nfor by someone other than me and there is no charge to me for the Program.\n\nThe **Purpose**\nof this authorization is for Quest to share my PHI with the Recipients so they can arrange for my testing, help deliver test results to me, help me understand my test results, and\n\nhelp me connect with healthcare professionals and health related programs.\n\n\"**PHI**\" means protected health information and includes my personal information (e.g., name,\n\naddress, age, gender, and other personal information) and any and all information related the testing performed/to be performed by Quest as part of the Program, including but not limited\n\nto, information to book appointment(s), my test results, and my laboratory report(s).\n\n**Recipients**\nmeans the following groups and individuals may receive my PHI :\nUnited Way of\n\nNew York City, Detroit Association of Black Organizations (DABO), Leadership Council for\n\nHealthy Communities (LCHC), MLK Community Resources Collaborative the church contracted\n\nby the above mentioned recipients to facilitate the Program (\"Church\");\nthe Church's on-site\n\nhealth navigator that may be in direct contact with me to help with the program;\nand the\n\nfollowing individuals that I identify (please insert the name of any other individuals you\n\nauthorize as a recipient of your PHI)________________________________________________________________________________________.\n\nOnce the Recipients have my PHI, it may no longer be protected under federal privacy law called HIPAA and it could be re-disclosed or re-shared to others.\n\nThis Authorization takes effect when I sign it;\nmy authorization will expire on December 31,\n\n-\n\n**`Notice to Patient:`**\n\n-\n\n**This authorization is voluntary and you may refuse to sign it.**\n\n- Quest cannot require you to sign this Authorization as a condition to providing its regular testing services, but because the Recipients identified above are arranging for testing as part of the\n\nProgram according to their eligibility requirements, including use of a health navigator, if you do not\n\nsign this Authorization you cannot participate in the Program or receive testing as part of the\n\nProgram.\n\n- You may ask for a copy of your PHI that will be used by or disclosed or shared to the Recipients;\n\n- Quest must give you a copy of this signed authorization, upon request;\n\n- This Authorization only covers your PHI that is collected, used or disclosed by Quest.\n\n- You have the right to revoke or take back this authorization at any time, by sending a written notice\n\nof revocation to CHLRevokeHIPAA@questdiagnostics.com.\n\nYour revocation only applies to uses and\n\ndisclosures of your information after we receive it, and does not affect any prior use or disclosure\n\nQuest made in reliance upon this authorization.\n\nI have read and understand this document and authorize the collection, use, and disclosure of my PHI as\n\nset forth above.",
  "Crown 2023 Custom Consent": "**HEALTHWISE SCREENING PROGRAM CONSENT**\n\nThe HealthWise Screening Program is a voluntary wellness program available to all full time Crown Equipment Corporation employees.\n\nThe program is administered according to federal rules permitting employer-sponsored wellness programs that seek to improve employee health or prevent disease, including the Americans with Disabilities Act of 1990, the Genetic Information Nondiscrimination Act of 2008, and the Health Insurance Portability and Accountability Act, as applicable, among others.\n\nIf you choose to participate in the wellness program, you will be asked to complete a voluntary health questionnaire that asks a series of questions about your health-related activities and behaviors and whether you have or had certain medical conditions (e.g., cancer, diabetes, or heart disease).\n\nYou will also be asked to complete a wellness screening, which will include collecting biometrics and a blood test for a lipid panel and hemoglobin A1c.\n\nYou are not required to complete the health questionnaire to participate in the wellness screening.\n\nThe information from your health questionnaire and the results from your wellness screening will provide you with information to help you understand your current health and potential risks and may also be used to offer you services through the wellness program.\n\nYou are encouraged to share your results or concerns with your healthcare provider.\n\n**Protections from Disclosure of Medical Information**\n\nWe are required by law to maintain the privacy and security of your personally identifiable health information.\n\nAlthough the HealthWise wellness program and Crown Equipment Corporation may use aggregate information it collects to design a program based on identified health risks in the workplace, the HealthWise Screening Program will never disclose any of your personal information either publicly or to Crown's personnel, except as necessary to respond to a request from you for a reasonable accommodation needed to participate in the wellness program, or as expressly permitted by law.\n\nMedical information that personally identifies you that is provided in connection with the wellness program will not be provided to your supervisors or managers and never be used to make decisions regarding your employment.\n\nYour health information will not be sold.\n\nIt will also not be exchanged, transferred, or otherwise disclosed except to the extent permitted by law to carry out specific activities related to the wellness program, and you will not be asked or required to waive the confidentiality of your health information as a condition of participating in this wellness program or receiving an incentive.\n\nAnyone who receives your information for purposes of providing you services as part of the wellness program will abide by the same confidentiality requirements.\n\nThe only entities who will receive your personally identifiable health information are Quest Diagnostics Health & Wellness, Joint Township District Memorial Hospital (JTDMH), Mercer County Joint Township Community Hospital (Mercer Health), and Putnam County Hospital to provide confidential services for participation in the HealthWise Screening Program.\n\nIn addition, all medical information obtained through this wellness program will be maintained separate from your personnel records, information stored electronically will be encrypted, and no information you provide as part of the wellness program will be used in making any employment decision.\n\nYour privacy is important to Crown, and Crown has in place an official Privacy Policy for your protection.\n\nAppropriate precautions will be taken to avoid any data breach, and in the event a data breach occurs involving information you provide in connection with the wellness program, we will notify you immediately.\n\nYou will not be discriminated against in employment because of the medical information you provide as part of participating in the wellness program, nor will you be subjected to retaliation if you choose not to participate.\n\nIf you have questions or concerns regarding this notice, or about protections against discrimination and retaliation, please contact the Crown Human Resources Department at 419-629- 2311.\n\n**I have read the information above and agree to participate in the HealthWise Screening Program.**\n\n**I understand that my participation in the program is voluntary and confidential and that I am not required to participate as a condition of employment or of enrollment in health insurance.**\n\n**I understand that the health questionnaire is completed at My.QuestForHealth.com and is a secure site managed by Quest Diagnostics Health & Wellness.**\n\n****strong text**I understand that Quest Diagnostics Health & Wellness, JTDMH, Mercer Health, and Putnam County Hospital will assist with the wellness screening program and follow standard protocol on any lab tests that exceeds a critical limit so that urgent medical treatment can be arranged.**\n\n**I understand that JTDMH and Mercer Health shall ensure that my lab results will be securely transmitted to Quest Diagnostics Health & Wellness and will be reported to My.QuestForHealth.com account.**\n\n**I understand it is my responsibility to follow-up with my healthcare provider to discuss my results and/or secure treatment when so advised.**\n\n**I understand that my personalized MyHealth Profile(TM) will be available online and mailed to my home after the wellness screening and health questionnaire is completed.**\n\n**I understand that Quest Diagnostics Health & Wellness will compile my results with those of other Crown employees and report to Crown only in the form of group statistics without any reference to me or my personal information.**\n\n**I understand that Crown will be informed that I have completed the health questionnaire and wellness screening to confirm my eligibility for a wellness incentive, but my individual responses and results will not be shared with Crown.**",
  "Occ Health": "Authorization\n\nI hereby authorize Quest Diagnostics Incorporated and its subsidiaries and affiliated companies (\"Quest Diagnostics\") to disclose my laboratory test results (\"Test Results\") as described in this Authorization to the company that is sponsoring this testing (\"Company\").\n\nThis Authorization applies to the following:\n\nAny and all drug tests, occupational health tests [perhaps will list them specifically];\nand any and all laboratory report(s) relating to COVID-19 testing.\n\nI authorize Quest Diagnostics to disclose the Test Results described above to Company.\n\nI am either an employee or independent contractor of Company, or am seeking to become an employee or independent contractor of Company.\n\nCompany is offering laboratory testing to certain employees independent contractors or potential employees or independent contractors for work-related purposes.\n\nThe purpose of the laboratory testing is to assist Company with the health and safety of Company's workforce and those with whom the workforce may interact, and I authorize the release of my Test Results for these purposes.\n\nThis Authorization becomes effective immediately upon my signature and shall expire one year\n\nfrom the date of my signature, whichever is later.\n\nI understand that:\n\n- This Authorization is voluntary, and I may refuse to sign it.\n\nIf I do not sign the Authorization, I am not eligible to receive the laboratory testing through Company's testing program.\n\n- I may revoke this Authorization at any time prior to its expiration date by sending a written revocation notice to Company.\n\nThe revocation will not have any effect on any actions taken in reliance on this Authorization.\n\n- Information used or disclosed pursuant to this Authorization will no longer be protected health information and may be subject to redisclosure by Company.\n\n- I have a right to a copy of this Authorization.\n\nBy signing this Authorization, I agree that I have read and understand it and authorize the disclosure of Test Results as set forth in this Authorization",
  "Qual Med": "I understand that Wellness Program services include health and wellness individualized counseling and/or biometric screening services and related programming, and that some or all of this information is my legally protected health information (\"PHI\").\n\nI authorize verbal and written release of my Wellness Program information to my health plan, health care vendor for health plan related purposes, and/or data analytics vendor for health care operations and quality assessment purposes by or to Quad/Med, LLC and its representatives, agents, and associated providers (\"QuadMed\").\n\nINFORMATION TO\nBE DISCLOSED:\nThe PHI disclosed pursuant to this authorization includes all Wellness Program related information and results, such as but not limited to, results of my tests, evaluations, diagnoses and medical history relevant to the tests and evaluations performed.\n\nThis information includes such details as my height, weight, body mass index, cholesterol profile, blood pressure, glucose testing, blood panel, biometric screening results, health risk assessment results, tobacco use information, incentive program tracking information, or any other general information that QuadMed already maintains about me from health related services.\n\nI understand the purpose of the use and/or disclosure authorized by this release is to conduct, administer, and evaluate the effectiveness and quality of the Wellness Program, health/disease management services, aggregate data for population health studies and overall health plan or provider improvement initiatives, health risk assessments, and/or benefit enrollment related to my participation in the health plan and/or my receipt of health related services.\n\nMY RIGHTS WITH\nRESPECT TO THIS\nAUTHORIZATION:\nThis Authorization is Voluntary.\n\nI understand this authorization is voluntary.\n\nUnless allowed by law, my refusal to sign this authorization will not affect my ability to receive treatment from QuadMed or associated health care providers.\n\nI also understand my refusal to sign this authorization will not affect my eligibility for or ability to enroll in my employer's health plan benefits.\n\nHowever, I understand that certain of the benefits of the Wellness Program, such as incentive rewards, may not be available to me without a signed authorization, as applicable.\n\nI understand that information used or disclosed as a result of this authorization may be subject to re-disclosure by the recipient and may no longer be protected by applicable privacy laws.\n\nRight to Revoke this Authorization.\n\nI understand that I have the right to revoke this authorization at any time.\n\nMy revocation will not apply to uses and disclosures that have already occurred under this authorization.\n\nI understand that my revocation is effective only if it is in writing.\n\nTo revoke my authorization, I understand that I must send a written request for revocation to QuadMed, Attention:\nPrivacy Officer, N64W23110 Main Street, Sussex, WI 53089.\n\nRight to Inspect and Copy.\n\nI understand that I have a right to inspect or obtain a copy of the PHI I have authorized to be used and/or disclosed by this authorization.\n\nRight to Receive a Copy of this Authorization.\n\nIf I agree to sign this authorization, which I am not required to do, I understand that I may download a copy of this form.\n\nExpiration.\n\nThis authorization expires one (1) year from the date of my signature below.\n\nI have had an opportunity to review and understand the content of this authorization.\n\nBy my electronic signature of this authorization, I am confirming that it accurately reflects my wishes and that I authorize QuadMed to use and disclose my PHI in accordance with the terms and conditions above.",
  "Occ Health Custom Consent": "I hereby authorize Quest Diagnostics Incorporated and its subsidiaries and affiliated companies (\"Quest Diagnostics\") to disclose my laboratory test results (\"Test Results\") as described in this Authorization to the company that is sponsoring this testing (\"Company\").\n\nThis Authorization applies to the following:\n\nAny and all drug tests, occupational health tests [perhaps will list them specifically];\nand any and all laboratory report(s) relating to COVID-19 testing.\n\nI authorize Quest Diagnostics to disclose the Test Results described above to Company.\n\nI am either an employee or independent contractor of Company, or am seeking to become an employee or independent contractor of Company.\n\nCompany is offering laboratory testing to certain employees independent contractors or potential employees or independent contractors for work-related purposes.\n\nThe purpose of the laboratory testing is to assist Company with the health and safety of Company's workforce and those with whom the workforce may interact, and I authorize the release of my Test Results for these purposes.\n\nThis Authorization becomes effective immediately upon my signature and shall expire one year from the date of my signature, whichever is later.\n\nI understand that:\n\nThis Authorization is voluntary and I may refuse to sign it.\n\nIf I do not sign the Authorization, I am not eligible to receive the laboratory testing through Company's testing program.\n\nI may revoke this Authorization at any time prior to its expiration date by sending a written revocation notice to Company.\n\nThe revocation will not have any effect on any actions taken in reliance on this Authorization.\n\nInformation used or disclosed pursuant to this Authorization will no longer be protected health information and may be subject to redisclosure by Company.\n\nI have a right to a copy of this Authorization.\n\nBy signing this Authorization, I agree that I have read and understand it and authorize the disclosure of Test Results as set forth in this Authorization.",
  "Asarco Consent": "HIPAA Release of Information\n\nAUTHORIZATION FORM\n\nI herby authorize Quest and its affiliates, its employees and agents to release to ASARCO LLC my personal health information, including all test results and any and all opinions, evaluations and recommendations regarding my ability to perform the essential functions of my position at ASARCO LLC.\n\nThis medical information may be used by the person(s) I authorize to receive this information for medical treatment or consultation, billing or claims payment, or other lawful purposes.\n\nThis authorization shall be in force and effect from the date of my/my representative's signature below and shall expire the earlier of my/my representative's written revocation of this authorization, or the date my employment at ASARCO LLC is terminated.\n\nI understand that I have the right to revoke this authorization, in writing, at any time.\n\nI understand that a revocation is not effective to the extent that any person or entity has already acted in reliance on my authorization or if my authorization was obtained as a condition of obtaining insurance coverage and the insurer has a legal right to contest a claim.\n\nI understand that my treatment, payment, enrollment, or eligibility for benefits will not be conditioned on whether I sign this authorization.\n\nI understand that information used or disclosed pursuant to this authorization may be disclosed by the recipient and may no longer be protected by federal or state law.",
  "HealthyQuest BFW HIPAA Authorization 08292025": "Blueprint for Wellness HIPAA Authorization\n\nQuest Diagnostics Clinical Laboratories, Inc.\n\n(Sponsor) sponsors the Group Welfare Plan of Quest Diagnostics (the Welfare Plan) which includes a variety of employee assistance programs.\n\nOne such program is the Blueprint for Wellness health screening and related wellness services (the Program).\n\nThe Program includes:\na clinical set of laboratory tests and measurements;\na health risk assessment;\nand wellness services for qualifying participants.\n\nThe Program is administered by the Welfare Plan and Quest Diagnostics Health & Wellness LLC (Workforce Health Solutions), which offers employer health screening events and employment drug testing solutions.\n\nThe clinical laboratory tests and measurements include, by way of example, blood testing for cotinine and other indicators of health risk/chronic conditions such as metabolic syndrome, diabetes, heart disease, etc.\n\nQuest Diagnostics Incorporated and its affiliated CLIA clinical testing laboratories (the Quest Labs) conduct the testing and clinical measurements that are part of the Program.\n\nWorkforce Health Solutions arranges for the services provided by the ordering healthcare provider (SteadyMD) and Quest Labs, administers the health risk assessment, and determines who meets the eligibility requirements, as determined by the Welfare Plan, for wellness services offered as part of the Program.\n\nThe Welfare Plan contracts with claims administrators (e.g., Aetna, UnitedHealthcare, University of Pittsburgh Medical Center Health Plan), health care providers, and providers of wellness services such as condition management, health coaching, smoking cessation, and incentive programs, to provide the administration and wellness services that are part of the Program (Wellness Service Providers).\n\nSome of the Wellness Service Providers may be subsidiaries or affiliates of Quest Diagnostics Incorporated.\n\nAs part of the Program, the Welfare Plan will receive the results of and information concerning your cotinine blood test and metabolic syndrome testing and measurements for the purposes of determining whether you qualify for an incentive or reward under the Welfare Plan (specifically, a reduction in bi-weekly medical contribution for medical plan enrollees (Incentives)).\n\nThe Welfare Plan is committed to helping you achieve your best health.\n\nRewards for participating in the Program are available to all employees enrolled in a Quest medical plan.\n\nIf you think you might be unable to meet a standard for a reward under the Program, you might qualify for an opportunity to earn the same reward by different means.\n\nA reasonable alternative program may be available to you, or you may submit a physician affidavit form confirming that you are under the care of a doctor.\n\nContact the Quest Diagnostics HR Service Center at (855)411-8511 or visit the Blueprint for Wellness page at QuestHRSC.com to learn more.\n\nThe Program is fully voluntary and offered at no cost to you.\n\nAs part of the Program, Quest Labs, Workforce Health Solutions, and the Welfare Plan may need to share some of your personal health information (also known as your protected health information or PHI) with the Recipients for the Purposes described below.\n\nAuthorization to Share PHI I give my permission and authorize Quest Labs, Workforce Health Solutions, and the Welfare Plan to collect, use and disclose my Blueprint for Wellness PHI to the groups and individuals named as Recipients for the Purposes as described below in this Authorization.\n\nThe Purpose of this authorization is to share your PHI with the Recipients (defined below) to arrange for the wellness services that you are eligible for through the Program.\n\nPHI means your personal information (e.g., name, address, age, gender, and other personal information) and any and all information related the clinical testing and measurements, and the health risk assessment as part of the Program, including but not limited to, information to book appointment(s), answers provided on your health questionnaire, your test results, your Metabolic Syndrome (MetS) Rewards score and your Blueprint for Wellness Health Quotient score).\n\nRecipients means the following groups and individuals, who will receive or have access to your PHI:\nQuest Diagnostics Incorporated personnel who share Program participant eligibility lists with Wellness Service Providers;\nQuest Diagnostics Incorporated personnel who are involved in administering the Incentives for qualifying participants;\nWellness Service Providers.\n\nTo the extent any Recipients are not HIPAA covered entities or business associates, once a Recipient has your PHI, it may no longer be protected under federal privacy law and it could be re-disclosed or re-shared to others.\n\nThis Authorization takes effect when I sign it;\nmy authorization will expire upon revocation or such shorter period (if any) required by state law.\n\nNotice to Patient:\n- This authorization is voluntary, and you may refuse to sign it.\n\n- Quest Labs cannot require you to sign this Authorization as a condition to providing its regular testing services, but because the Sponsor is paying for your participation in the Program, if you do not sign this Authorization you cannot participate in the Program or receive the testing or other services that are part of the Program.\n- You may ask for a copy of your PHI that will be used by or disclosed or shared with the Recipients.\n- We must give you a copy of this signed authorization, upon request.\n- This Authorization only covers your PHI that is collected, used or disclosed as part of the Program by Quest Labs and/or Workforce Health Solutions.\n\n- You have the right to revoke this authorization at any time, by sending a written notice of revocation to Quest Diagnostics Attn:\nBlueprint for Wellness Services, 9601 Renner Boulevard, Lenexa KS 66219.\n\nYour revocation only applies to uses and disclosures of your information after we receive it, and does not affect any prior use or disclosure Quest Labs and/or Workforce Health Solutions made in reliance upon this authorization.\n\nI have read and understand this document and authorize the collection, use, and disclosure of my PHI as set forth above.\n\nI agree to sign this Authorization electronically by selecting \"Accept.\"",
  "Quad med": "AUTHORIZATION TO\nUSE AND DISCLOSE\nPROTECTED HEALTH\nINFORMATION WELLNESS\nPROGRAM SERVICES\nI understand that Wellness Program services include health and wellness individualized counseling and/or biometric screening services and related programming, and that some or all of this information is my legally protected health information (\"PHI\").\n\nI authorize verbal and written release of my Wellness Program information to my health plan, health care vendor for health plan related purposes, and/or data analytics vendor for health care operations and quality assessment purposes by or to Quad/Med, LLC and its representatives, agents, and associated providers (\"QuadMed\").\n\nINFORMATION TO\nBE DISCLOSED:\nThe PHI disclosed pursuant to this authorization includes all Wellness Program related information and results, such as but not limited to, results of my tests, evaluations, diagnoses and medical history relevant to the tests and evaluations performed.\n\nThis information includes such details as my height, weight, body mass index, cholesterol profile, blood pressure, glucose testing, blood panel, biometric screening results, health risk assessment results, tobacco use information, incentive program tracking information, or any other information that QuadMed has or maintains about me from health-related services, whether provided directly or indirectly through a health information exchange or other electronic network.\n\nI understand the purpose of the use and/or disclosure authorized by this release is to conduct, administer, and evaluate the effectiveness and quality of the Wellness Program, health/disease management services, aggregate data for population health studies and overall health plan or provider improvement initiatives, health risk assessments, and/or my receipt of health-related services.\n\nMY RIGHTS WITH\nRESPECT TO THIS\nAUTHORIZATION:\nThis Authorization is Voluntary.\n\nI understand this authorization is voluntary.\n\nUnless allowed by law, my refusal to sign this authorization will not affect my ability to receive treatment from QuadMed or associated health care providers.\n\nI also understand my refusal to sign this authorization will not affect my eligibility for or ability to enroll in my employer's health plan benefits.\n\nHowever, I understand that certain of the benefits of the Wellness Program, such as incentive rewards, may not be available to me without a signed authorization, as applicable.\n\nI understand that information used or disclosed as a result of this authorization may be subject to re-disclosure by the recipient and may no longer be protected by applicable privacy laws.\n\nRight to Revoke this Authorization.\n\nI understand that I have the right to revoke this authorization at any time.\n\nMy revocation will not apply to uses and disclosures that have already occurred under this authorization.\n\nI understand that my revocation is effective only if it is in writing.\n\nTo revoke my authorization, I understand that I must send a written request for revocation to QuadMed, Attention:\nPrivacy Officer, W227N6103 Sussex Rd, Sussex, WI 53089.\n\nRight to Inspect and Copy.\n\nI understand that I have a right to inspect or obtain a copy of the PHI I have authorized to be used and/or disclosed by this authorization.\n\nRight to Receive a Copy of this Authorization.\n\nIf I agree to sign this authorization, which I am not required to do, I understand that I may download a copy of this form.\n\nExpiration.\n\nThis authorization expires one (1) year from the date of my signature below.\n\nI have had an opportunity to review and understand the content of this authorization.\n\nBy my electronic signature of this authorization, I am confirming that it accurately reflects my wishes and that I authorize QuadMed to use and disclose my PHI in accordance with the terms and conditions above.",
  "Honeywell Aerospace Custom Consent": "Honeywell Aerospace's wellness program (the Program) is voluntary and available to all employees.\n\nBy completing a biometric screening, you authorize the results to be sent from Quest Diagnostics to applicable service providers associated with the Program (Service Providers) including Cigna, or Castlight Health, for health navigation services, and Merative, a healthcare analytics solution provider.\n\nWe are required by law to maintain the privacy and security of your personally identifiable health information.\n\nAlthough the Program and Honeywell Aerospace may use aggregate information collected to design a program based on identified health risks in the workplace, neither the Program nor the Service Providers will disclose any of your personal information either publicly or to Honeywell Aerospace, except as necessary to respond to a request from you for a reasonable accommodation needed to participate in the Program, or as expressly permitted by law.\n\nMedical information that personally identifies you that is provided in connection with the Program will not be provided to your supervisors or managers and may never be used to make decisions regarding your employment."
};

var consent_instruction = dictionary[ZT.getVariableValue("company", "")] || "";
ZT.setFormData("consent_instruction", consent_instruction);
